_NUMBER_PATTERN = re.compile(r"[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?")

def task_func(json_str):
    if json_str is None or not str(json_str).strip():
        return pd.DataFrame()

    try:
        data = json.loads(json_str)
    except (TypeError, ValueError, json.JSONDecodeError):
