        return float(value) * 2.0
    if isinstance(value, str):
        match = _NUMBER_RE.search(value)
        if match is not None:
            try:
                return float(match.group()) * 2.0
            except ValueError:
                return value
        return value
    if isinstance(value, list):
        return [_normalize_value(item) for item in value]
