        return pd.DataFrame()

    try:
        data = json.loads(json_str)
    except (json.JSONDecodeError, TypeError, ValueError):
        return pd.DataFrame()

    if not isinstance(data, dict):
        return pd.DataFrame()

    normalized = {}
    for key, value in data.items():
        if isinstance(value, dict):
            continue
        normalized[key] = _normalize_value(value)

    if not normalized:
        return pd.DataFrame()

    try:
        has_list_like = any(isinstance(v, (list, tuple, pd.Series, pd.Index)) for v in normalized.values())
        if not has_list_like:
            return pd.DataFrame([normalized])
        return pd.DataFrame(normalized)
    except Exception:
        return pd.DataFrame()
