import subprocess
import os
import signal
import time


def _parse_tasklist_csv_line(line: str) -> list[str]:
    fields = []
    field = []
    in_quotes = False
    i = 0

    while i < len(line):
        ch = line[i]
        if in_quotes:
            if ch == '"':
                if i + 1 < len(line) and line[i + 1] == '"':
                    field.append('"')
                    i += 1
                else:
                    in_quotes = False
            else:
                field.append(ch)
        else:
            if ch == ',':
                fields.append("".join(field))
                field = []
            elif ch == '"':
                in_quotes = True
            elif not (ch.isspace() and not field and not fields):
                field.append(ch)
        i += 1

    fields.append("".join(field))
    return fields


def _normalize_windows_name(name: str) -> str:
    normalized = name.strip().lower()
    if normalized.endswith(".exe"):
        normalized = normalized[:-4]
    return normalized


def _iter_processes():
    if os.name == "nt":
        output = subprocess.check_output(
            ["tasklist", "/fo", "csv", "/nh"],
            text=True,
            stderr=subprocess.DEVNULL,
            errors="replace",
        )
        for line in output.splitlines():
            line = line.strip()
            if not line:
                continue
            fields = _parse_tasklist_csv_line(line)
            if len(fields) < 2:
                continue
            try:
                pid = int(fields[1].strip())
            except ValueError:
                continue
            yield pid, fields[0].strip()
    else:
        output = subprocess.check_output(
            ["ps", "-A", "-o", "pid=", "-o", "comm="],
            text=True,
            stderr=subprocess.DEVNULL,
            errors="replace",
        )
        for line in output.splitlines():
            line = line.strip()
            if not line:
                continue
            parts = line.split(None, 1)
            if len(parts) != 2:
                continue
            try:
                pid = int(parts[0])
            except ValueError:
                continue
            yield pid, parts[1].strip()


def task_func(process_name: str) -> int:
    target = process_name.strip()
    if not target:
        return 0

    stopped = 0

    try:
        processes = list(_iter_processes())
    except Exception:
        return 0

    if os.name == "nt":
        target_norm = _normalize_windows_name(target)
        for pid, name in processes:
            if _normalize_windows_name(name) != target_norm:
                continue
            try:
                os.kill(pid, signal.SIGTERM)
            except (ProcessLookupError, PermissionError, OSError):
                continue
            stopped += 1
    else:
        for pid, name in processes:
            if name != target:
                continue
            try:
                os.kill(pid, signal.SIGTERM)
            except (ProcessLookupError, PermissionError, OSError):
                continue
            stopped += 1

    if stopped:
        time.sleep(1)
    return stopped
