                    capture_output=True,
                    text=True,
                    check=False,
                )
                for line in result.stdout.splitlines():
                    line = line.strip()
                    if not line or line.startswith("INFO:"):
                        continue
                    if not (line.startswith('"') and line.endswith('"')):
                        continue
                    fields = line[1:-1].split('","')
                    if len(fields) < 2:
                        continue
                    image = fields[0].strip()
                    pid_str = fields[1].strip()
                    if image.lower() != target_name_cmp:
                        continue
                    try:
                        pid = int(pid_str)
                    except ValueError:
                        continue
                    if pid != current_pid:
                        pids.append(pid)
            else:
                result = subprocess.run(
                    ["ps", "-A", "-o", "pid=,comm="],
                    capture_output=True,
                    text=True,
                    check=False,
                )
                for line in result.stdout.splitlines():
                    line = line.strip()
                    if not line:
                        continue
                    parts = line.split(None, 1)
                    if len(parts) != 2:
                        continue
                    pid_str, name = parts[0].strip(), parts[1].strip()
                    if name != target_name:
                        continue
                    try:
                        pid = int(pid_str)
                    except ValueError:
                        continue
                    if pid != current_pid:
                        pids.append(pid)
        except Exception:
            return []
        return pids

    initial_pids = _list_matching_pids()
    if not initial_pids:
        return 0

    for pid in initial_pids:
        try:
            os.kill(pid, signal.SIGTERM)
        except OSError:
            pass

    time.sleep(1)

    remaining_pids = set(_list_matching_pids())
